/**
 * The in-process media module against real media generated by the test
 * helper. Nothing here runs the ffmpeg or ffprobe binaries.
 */

import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";

import { afterAll, beforeAll, describe, expect, it } from "vitest";

import {
  convertAudioToWav,
  decodeAudioToPcm,
  muxAudioWithVideoCopy,
  openFilterComplex,
  openFilterGraph,
  openRgbaFrameReader,
  openVideoFrameEncoder,
  packetTimes,
  probeMedia,
  trimVideo
} from "../../src/media/index.js";
import {
  encodeWav,
  generateMedia,
  inspectMedia,
  meanRgba,
  readPcm,
  readRgbaFrames,
  rmsBetween,
  sineSamples,
  solidRgba,
  writeRgbaVideo
} from "../../src/media/testing.js";

let dir: string;
const file = (name: string): string => path.join(dir, name);

beforeAll(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), "nodetool-media-module-"));
  await generateMedia({
    outPath: file("av.mp4"),
    video: {
      source: "testsrc2=size=96x64:rate=24:duration=2",
      options: { g: "12", bf: "2" }
    },
    audio: { source: "sine=frequency=440:sample_rate=48000:duration=2" }
  });
  // Two frames of every five on a 60 fps lattice: the profile generated clips have.
  await generateMedia({
    outPath: file("vfr.mkv"),
    video: {
      source: "testsrc2=size=32x24:rate=60:duration=4",
      filter: "select='lt(mod(n\\,5)\\,2)'",
      codec: "ffv1",
      pixelFormat: "bgra"
    }
  });
  await fs.writeFile(
    file("tone.wav"),
    encodeWav(
      sineSamples({ sampleRate: 44100, channels: 2, durationSec: 1, frequency: 1000 }),
      44100,
      2
    )
  );
});

afterAll(async () => {
  if (dir) await fs.rm(dir, { recursive: true, force: true });
});

describe("probeMedia", () => {
  it("reads streams, size and duration", async () => {
    const probe = await probeMedia(file("av.mp4"));
    expect(probe.video).toMatchObject({ codec: "avc", width: 96, height: 64 });
    expect(probe.video?.nominalFps).toBe(24);
    expect(probe.audio).toMatchObject({ codec: "aac", sampleRate: 48000, channels: 1 });
    expect(probe.durationSec).toBeGreaterThan(1.9);
    expect(probe.durationSec).toBeLessThan(2.1);
  });

  it("separates the lattice rate from the average of a variable-rate file", async () => {
    const probe = await probeMedia(file("vfr.mkv"), { frameRatePackets: Infinity });
    expect(probe.video?.nominalFps).toBe(60);
    expect(probe.video?.averageFps).toBeGreaterThan(23);
    expect(probe.video?.averageFps).toBeLessThan(25);
    expect(probe.video?.constantFrameRate).toBe(false);
    expect(probe.audio).toBeNull();
  });

  it("throws on bytes that are no container", async () => {
    await expect(probeMedia(new Uint8Array([1, 2, 3, 4, 5]))).rejects.toThrow();
  });
});

describe("packetTimes", () => {
  it("lists every video packet in seconds", async () => {
    const times = await packetTimes(file("av.mp4"));
    expect(times).toHaveLength(48);
    const sorted = [...(times ?? [])].sort((a, b) => a - b);
    expect(sorted[1]).toBeCloseTo(1 / 24, 3);
  });

  it("gives up past maxPackets", async () => {
    expect(await packetTimes(file("av.mp4"), { maxPackets: 10 })).toBeNull();
  });
});

describe("decodeAudioToPcm", () => {
  it("resamples and downmixes with a pan filter", async () => {
    const pcm = await decodeAudioToPcm(file("tone.wav"), {
      sampleRate: 48000,
      filter: "pan=mono|c0=0.5*c0+0.5*c1"
    });
    expect(pcm.channels).toBe(1);
    expect(pcm.samples.length).toBeGreaterThan(47000);
    expect(pcm.samples.length).toBeLessThan(49000);
    // A 0.5 sine has RMS 0.5/√2.
    expect(rmsBetween(pcm, 0.1, 0.9)).toBeCloseTo(0.5 / Math.SQRT2, 2);
  });

  it("stops at maxSeconds", async () => {
    const pcm = await decodeAudioToPcm(file("tone.wav"), {
      sampleRate: 44100,
      channels: 2,
      maxSeconds: 0.25
    });
    expect(pcm.samples.length).toBe(0.25 * 44100 * 2);
  });

  it("rejects a file without audio", async () => {
    await expect(decodeAudioToPcm(file("vfr.mkv"), { sampleRate: 48000 })).rejects.toThrow(
      /no audio/
    );
  });
});

describe("filter graphs", () => {
  it("runs a single-input chain", async () => {
    const run = await openFilterGraph({
      filePath: file("tone.wav"),
      kind: "audio",
      filter: "volume=0,aformat=sample_fmts=flt"
    });
    expect(run).not.toBeNull();
    let peak = 0;
    for await (const frame of run!.frames()) {
      const samples = new Float32Array(new Uint8Array(frame.toBuffer()).buffer);
      for (const value of samples) peak = Math.max(peak, Math.abs(value));
      frame.free();
    }
    await run!.close();
    expect(peak).toBe(0);
  });

  it("mixes several inputs by label, one file read twice", async () => {
    const run = await openFilterComplex({
      inputs: [
        { filePath: file("tone.wav"), kind: "audio", label: "0:a" },
        { filePath: file("tone.wav"), kind: "audio", label: "1:a" }
      ],
      graph: "[0:a]adelay=500|500[d];[d][1:a]amix=inputs=2:duration=longest:normalize=0,aformat=sample_fmts=flt:channel_layouts=stereo[out]",
      output: "out",
      outputKind: "audio"
    });
    const chunks: Float32Array[] = [];
    for await (const frame of run.frames()) {
      chunks.push(new Float32Array(new Uint8Array(frame.toBuffer()).buffer));
      frame.free();
    }
    await run.close();
    const samples = Float32Array.from(chunks.flatMap((chunk) => [...chunk]));
    const audio = { samples, sampleRate: 44100, channels: 2 };
    // 1.5 s long; the two copies overlap between 0.5 s and 1 s, doubling the level.
    expect(samples.length / 2 / 44100).toBeCloseTo(1.5, 2);
    const single = rmsBetween(audio, 0.1, 0.4);
    expect(rmsBetween(audio, 0.6, 0.9) / single).toBeCloseTo(2, 1);
    expect(rmsBetween(audio, 1.1, 1.4) / single).toBeCloseTo(1, 1);
  });

  it("refuses an input with no stream of its kind", async () => {
    await expect(
      openFilterComplex({
        inputs: [{ filePath: file("vfr.mkv"), kind: "audio", label: "0:a" }],
        graph: "[0:a]anull[out]",
        output: "out",
        outputKind: "audio"
      })
    ).rejects.toThrow(/no audio stream/);
  });
});

describe("RGBA decode and encode", () => {
  it("round-trips exact pixels through a lossless encode", async () => {
    const colors: [number, number, number, number][] = [
      [255, 0, 0, 255],
      [0, 255, 0, 128],
      [0, 0, 255, 0]
    ];
    await writeRgbaVideo({
      outPath: file("rgba.mkv"),
      width: 20,
      height: 10,
      fps: 30,
      frames: colors.length,
      frameAt: (index) => solidRgba(20, 10, colors[index] ?? [0, 0, 0, 0])
    });
    const frames = await readRgbaFrames(file("rgba.mkv"), { width: 20, height: 10 });
    expect(frames.map((frame) => meanRgba(frame))).toEqual(colors);
  });

  it("seeks like -ss: the first frame is the one at the seek time", async () => {
    await writeRgbaVideo({
      outPath: file("gray.mkv"),
      width: 8,
      height: 8,
      fps: 10,
      frames: 20,
      frameAt: (index) => solidRgba(8, 8, [index * 10, index * 10, index * 10, 255])
    });
    const reader = await openRgbaFrameReader({
      filePath: file("gray.mkv"),
      filter: "format=rgba",
      seekSec: 1.05
    });
    const first = await reader!.next();
    await reader!.close();
    // Frame 11 (t = 1.1) is the first at or after 1.05 s.
    expect(meanRgba(first!.rgba)[0]).toBe(110);
    expect(first!.ptsSec).toBeCloseTo(0.05, 3);
  });

  it("encodes H.264 with BT.709 tags from RGBA", async () => {
    const encoder = await openVideoFrameEncoder({
      outPath: file("bt709.mp4"),
      fps: 25,
      input: "rgba",
      width: 32,
      height: 16,
      spec: {
        codec: "libx264",
        pixelFormat: "yuv420p",
        filter: "scale=out_color_matrix=bt709:out_range=tv",
        options: {
          preset: "veryfast",
          colorspace: "bt709",
          color_primaries: "bt709",
          color_trc: "bt709"
        }
      }
    });
    for (let i = 0; i < 25; i++) await encoder.write(solidRgba(32, 16, [200, 40, 40, 255]));
    await encoder.finish();
    const report = await inspectMedia(file("bt709.mp4"));
    expect(report.video).toMatchObject({ codec: "avc", width: 32, height: 16 });
    expect(report.frameTimes).toHaveLength(25);
    const [frame] = await readRgbaFrames(file("bt709.mp4"), { width: 32, height: 16 });
    const [r, g, b] = meanRgba(frame!);
    expect(Math.abs(r - 200)).toBeLessThan(4);
    expect(Math.abs(g - 40)).toBeLessThan(4);
    expect(Math.abs(b - 40)).toBeLessThan(4);
  });

  it("stops a reader that is never drained", async () => {
    const reader = await openRgbaFrameReader({
      filePath: file("av.mp4"),
      filter: "format=rgba",
      readAhead: 2
    });
    await reader!.next();
    await reader!.close();
    expect(await reader!.next()).toBeNull();
  });

  it("aborts an encode", async () => {
    const controller = new AbortController();
    const encoder = await openVideoFrameEncoder({
      outPath: file("aborted.mp4"),
      fps: 25,
      input: "rgba",
      width: 16,
      height: 16,
      spec: { codec: "libx264", pixelFormat: "yuv420p" },
      signal: controller.signal
    });
    await encoder.write(solidRgba(16, 16, [0, 0, 0, 255]));
    controller.abort();
    await expect(encoder.write(solidRgba(16, 16, [0, 0, 0, 255]))).rejects.toThrow();
  });
});

describe("muxAudioWithVideoCopy", () => {
  it("copies the picture and ends the audio with it", async () => {
    const run = await openFilterComplex({
      inputs: [{ filePath: file("tone.wav"), kind: "audio", label: "1:a" }],
      graph: "[1:a]adelay=200|200,apad[aout]",
      output: "aout",
      outputKind: "audio"
    });
    try {
      await muxAudioWithVideoCopy({
        videoPath: file("av.mp4"),
        audio: run.frames(),
        outPath: file("muxed.mp4"),
        codec: "aac",
        sampleRate: 48000
      });
    } finally {
      await run.close();
    }
    const report = await inspectMedia(file("muxed.mp4"));
    expect(report.frameTimes).toHaveLength(48);
    expect(report.audio).toMatchObject({ sampleRate: 48000, channels: 2 });
    const pcm = await readPcm(file("muxed.mp4"), { sampleRate: 48000, channels: 2 });
    const seconds = pcm.samples.length / 2 / 48000;
    expect(seconds).toBeGreaterThan(1.95);
    expect(seconds).toBeLessThan(2.1);
    expect(rmsBetween(pcm, 0, 0.15)).toBeLessThan(0.01);
    expect(rmsBetween(pcm, 0.4, 1.0)).toBeGreaterThan(0.3);
    expect(rmsBetween(pcm, 1.4, 1.9)).toBeLessThan(0.01);
  });
});

describe("audio encode", () => {
  it("keeps the last partial frame", async () => {
    // 8000 samples is 7.8 AAC frames; node-av's own encoder drops the 0.8.
    await generateMedia({
      outPath: file("tail.m4a"),
      audio: { source: "sine=frequency=440:sample_rate=8000:duration=1" }
    });
    const pcm = await readPcm(file("tail.m4a"), { sampleRate: 8000, channels: 1 });
    expect(pcm.samples.length).toBeGreaterThanOrEqual(8000);
    expect(pcm.samples.length).toBeLessThan(8000 + 1024);
    expect(rmsBetween(pcm, 0.9, 1)).toBeGreaterThan(0.05);
  });
});

describe("Mediabunny conversions", () => {
  it("trims to a window that starts at zero", async () => {
    const bytes = await trimVideo(await fs.readFile(file("av.mp4")), 0.5, 1.5);
    await fs.writeFile(file("trim.mp4"), bytes);
    const report = await inspectMedia(file("trim.mp4"));
    expect(report.video?.codec).toBe("avc");
    expect(report.audio?.codec).toBe("aac");
    expect(report.frameTimes[0]).toBeCloseTo(0, 3);
    expect(report.durationSec).toBeGreaterThan(0.95);
    expect(report.durationSec).toBeLessThan(1.1);
  });

  it("writes 16-bit WAV at the source rate", async () => {
    await convertAudioToWav(file("av.mp4"), file("out.wav"));
    const probe = await probeMedia(file("out.wav"));
    expect(probe.audio).toMatchObject({ codec: "pcm-s16", sampleRate: 48000, channels: 1 });
    expect(probe.durationSec).toBeCloseTo(2, 1);
  });

  it("refuses a WAV from a file without audio", async () => {
    await expect(convertAudioToWav(file("vfr.mkv"), file("none.wav"))).rejects.toThrow(
      /no audio/
    );
  });
});
